#' Maximum Likelihood Estimation (D3/D5)
#'
#' 
#' @param data .
#' @param var .
#' @param bindistr .
#' @param geodistr .
#' @param podistr .
#' @param Ndistr .
#' @param expdistr .
#' @param Udistr .
#' @param pardistr .
#' @param powdistr .
#' @param variance .
#' @param mean .
#' @param mu .
#' @param expparameter .
#' @param unifa .
#' @param a .
#' @param unifb .
#' @param b .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$MLEbin} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEgeo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEpo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEnorm} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEexp} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEunif} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEpar} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$MLEpow} \tab \tab \tab \tab \tab a table \cr
