#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$MLEbin$asDF}
#'
#' \code{as.data.frame(results$MLEbin)}
#'
#' @export
d3maximumlikelihood <- function(
    data,
    var,
    bindistr = FALSE,
    geodistr = FALSE,
    podistr = FALSE,
    Ndistr = FALSE,
    expdistr = FALSE,
    Udistr = FALSE,
    pardistr = FALSE,
    powdistr = FALSE,
    variance = FALSE,
    mean = FALSE,
    mu = 0,
    expparameter,
    unifa = FALSE,
    a = 0,
    unifb = FALSE,
    b = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("d3maximumlikelihood requires jmvcore to be installed (restart may be required)")

    if ( ! missing(var)) var <- jmvcore::resolveQuo(jmvcore::enquo(var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(var), var, NULL))


    options <- d3maximumlikelihoodOptions$new(
        var = var,
        bindistr = bindistr,
        geodistr = geodistr,
        podistr = podistr,
        Ndistr = Ndistr,
        expdistr = expdistr,
        Udistr = Udistr,
        pardistr = pardistr,
        powdistr = powdistr,
        variance = variance,
        mean = mean,
        mu = mu,
        expparameter = expparameter,
        unifa = unifa,
        a = a,
        unifb = unifb,
        b = b)

    analysis <- d3maximumlikelihoodClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

